function circlePath(r: number): string {
  const v = r.toFixed(1);
  return `M -${v} 0 A ${v} ${v} 0 1 0 ${v} 0 A ${v} ${v} 0 1 0 -${v} 0 Z`;
}

export function getCutterOutlineKind(code: string): CutterOutlineKind {
  const normalized = String(code || '').trim().toUpperCase();
  if (/^(?:\d|Y\d)/.test(normalized)) return 'roller';
  if (/^(?:S|G|H)\d/.test(normalized)) return 'scraper';
  return 'ripper';
}

export function getCutterOutline(position: CutterOutlinePosition): CutterOutline {
  const key = String(position.code || '').trim().toUpperCase();
  const kind = getCutterOutlineKind(key);
  const entry = OUTLINES[key];

  if (!entry) {
    const r = kind === 'roller' ? 34 : 23;
    return {
      kind,
      transform: `translate(${position.x} ${position.y})`,
      path: circlePath(r),
      detailPath: '',
      hitRadius: r,
      hasRealOutline: false,
    };
  }

  const [cx, cy, r, detail] = entry;
  return {
    kind,
    transform: `translate(${cx} ${cy})`,
    path: circlePath(r),
    detailPath: detail,
    hitRadius: r,
    hasRealOutline: detail.length > 0,
  };
}

/** 有真实图纸轮廓的刀位数量，便于自检 */
export const REAL_OUTLINE_COUNT = Object.values(OUTLINES).filter(e => e[3].length > 0).length;
